/*
 * A273338  Alternate version of A273317 with rows sorted in ascending order.
 * https://oeis.org/A273338
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   not stated
 * Range:     u8 n <= 9, u16 n <= 29, u32 n <= 60, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Helpers:   seq_cmp
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A273338: Triangular array generated by
   starting from 2 and, for each row of length n, applying all
   sequences of n operations where each operation is either
   "+1" or "* (x+1)", then sorting the row ascending.
   The sequence is the concatenation of the rows. */
#include <stdlib.h>
#include <stdint.h>
#include "../utils/seq_cmp.h"

seq_t a(idx_t n)
{
    /* Find the row r such that 2^r - 1 <= n < 2^(r+1) - 1   */
    idx_t tmp = n + 1;
    idx_t r = 0;
    while (tmp > 1) {
        tmp >>= 1;
        ++r;
    }

    /* position of n within its row */
    idx_t start = ((idx_t)1 << r) - 1;
    idx_t pos   = n - start;

    /* static cache for each row that has been generated */
    static seq_t *rows[64];
    static size_t row_sizes[64] = {0};

    if (row_sizes[r] == 0) {
        size_t sz = (size_t)1 << r;
        seq_t *row = (seq_t *)malloc(sz * sizeof(seq_t));
        if (!row) { /* out of memory – abort */
            abort();
        }

        /* generate all 2^r values by interpreting the
           index i as a sequence of operations
           (bit 0 → +1, bit 1 → * (x+1)) */
        for (size_t i = 0; i < sz; ++i) {
            seq_t val = (seq_t)2;
            for (idx_t k = 0; k < r; ++k) {
                int bit = ((i >> (r - 1 - k)) & 1);
                if (bit == 0) {
                    val += (seq_t)1;
                } else {
                    val = val * (val + (seq_t)1);
                }
            }
            row[i] = val;
        }

        /* sort the row in ascending order */
        qsort(row, sz, sizeof(seq_t), seq_cmp);

        rows[r] = row;
        row_sizes[r] = sz;
    }

    return rows[r][pos];
}
